export class Euler {
    _x;
    _y;
    _z;
    _order;
    changed;
    constructor(x = 0, y = 0, z = 0, order = 'XYZ', onChange) {
        this._x = x;
        this._y = y;
        this._z = z;
        this._order = order;
        this.changed = onChange;
    }
    get x() { return this._x; }
    set x(value) { this._x = value; this.changed?.(); }
    get y() { return this._y; }
    set y(value) { this._y = value; this.changed?.(); }
    get z() { return this._z; }
    set z(value) { this._z = value; this.changed?.(); }
    get order() { return this._order; }
    set order(value) { this._order = value; this.changed?.(); }
    set(x, y, z, order = this._order) { this._x = x; this._y = y; this._z = z; this._order = order; this.changed?.(); return this; }
    copy(value) { return this.set(value.x, value.y, value.z, value.order); }
    clone() { return new Euler(this._x, this._y, this._z, this._order); }
    setFromQuaternion(value) {
        if (this._order !== 'XYZ')
            throw new Error(`Euler order ${this._order} is not implemented for quaternion conversion.`);
        const sinr = 2 * (value.w * value.x + value.y * value.z);
        const cosr = 1 - 2 * (value.x * value.x + value.y * value.y);
        const x = Math.atan2(sinr, cosr);
        const sinp = 2 * (value.w * value.y - value.z * value.x);
        const y = Math.abs(sinp) >= 1 ? Math.sign(sinp) * Math.PI / 2 : Math.asin(sinp);
        const siny = 2 * (value.w * value.z + value.x * value.y);
        const cosy = 1 - 2 * (value.y * value.y + value.z * value.z);
        return this.set(x, y, Math.atan2(siny, cosy), this._order);
    }
}